const exercises=[
{id:'squat',name:'Sentadilla',goal:'fuerza',region:'inferior',level:'inicial',movement:'squat',case:'sentadilla',joints:'Cadera, rodilla y tobillo',bones:'Pelvis, fémur, tibia y pie',muscles:'Glúteo mayor, cuádriceps y sóleo',phases:['Descenso: flexión de cadera y rodilla','Transición: cambia la dirección del movimiento','Ascenso: extensión de cadera y rodilla'],mechanics:'La distancia de la carga respecto a cadera y rodilla modifica los momentos externos. La distribución cambia con la postura y el apoyo.',question:'¿Qué articulaciones deben extenderse al subir?',answer:'Cadera y rodilla; el tobillo también participa según la ejecución.'},
{id:'hiphinge',name:'Bisagra de cadera',goal:'fuerza',region:'tronco',level:'inicial',movement:'hiphinge',case:'bisagra',joints:'Cadera y columna como referencia',bones:'Pelvis, fémur y columna',muscles:'Glúteo mayor, isquiotibiales y erectores espinales',phases:['Inicio: base de apoyo y cadera neutra','Descenso: flexión predominante de cadera','Regreso: extensión de cadera'],mechanics:'Alejar una carga de la cadera aumenta su brazo de momento externo. El tronco necesita control mientras se mueve la cadera.',question:'¿Qué cambia si la carga se aleja del cuerpo?',answer:'Aumenta su brazo de momento respecto a la cadera, si las demás condiciones permanecen iguales.'},
{id:'chestpress',name:'Press de pecho',goal:'fuerza',region:'superior',level:'intermedio',movement:'chestpress',case:'press-pecho',joints:'Hombro y codo',bones:'Escápula, clavícula, húmero, radio y cúbito',muscles:'Pectoral mayor, deltoides anterior y tríceps braquial',phases:['Preparación: codos flexionados','Empuje: hombro avanza y codo se extiende','Retorno: se controla la resistencia'],mechanics:'La dirección de la resistencia y la posición del brazo alteran los momentos en hombro y codo; el resaltado no mide activación.',question:'¿Qué función articular aporta el tríceps?',answer:'Extiende el codo durante el empuje.'},
{id:'row',name:'Remo',goal:'fuerza',region:'superior',level:'intermedio',movement:'row',case:'hombro',joints:'Hombro, codo y complejo escapular',bones:'Escápula, húmero, radio y cúbito',muscles:'Dorsal ancho, redondo mayor, braquial y bíceps',phases:['Brazos extendidos hacia la resistencia','Tracción: hombro y codo se mueven','Retorno controlado'],mechanics:'La línea de tracción crea momentos distintos en hombro y codo. La escápula real se mueve, aunque su animación aquí es limitada.',question:'¿Qué dos articulaciones explican la mayor parte de la tracción mostrada?',answer:'Hombro y codo.'},
{id:'walkstep',name:'Dar un paso',goal:'vida',region:'inferior',level:'inicial',movement:'walkstep',case:'marcha',joints:'Cadera, rodilla y tobillo de ambos lados',bones:'Pelvis, fémures, tibias y pies',muscles:'Glúteos, flexores de cadera, isquiotibiales y plantarflexores',phases:['Apoyo de una pierna','Balanceo de la pierna opuesta','Preparación del siguiente apoyo'],mechanics:'El apoyo y el balanceo exigen tareas diferentes. El visor no calcula fuerzas de reacción del suelo.',question:'¿Qué pierna soporta el cuerpo durante apoyo unilateral?',answer:'La pierna que permanece en contacto con el suelo.'},
{id:'pickup',name:'Recoger un objeto',goal:'vida',region:'tronco',level:'inicial',movement:'pickup',case:'bisagra',joints:'Cadera, rodilla, hombro y codo',bones:'Pelvis, fémur, columna y brazo',muscles:'Glúteos, isquiotibiales, erectores espinales y músculos del brazo',phases:['Preparar la base de apoyo','Inclinarse y alcanzar','Aproximar el objeto y erguirse'],mechanics:'La posición del objeto cambia el brazo de momento respecto a la cadera. El modelo no representa su masa.',question:'¿Por qué importa la distancia del objeto al cuerpo?',answer:'Porque modifica el brazo de momento externo de su peso.'},
{id:'stairup',name:'Subir un escalón',goal:'vida',region:'inferior',level:'intermedio',movement:'stairup',case:'sentadilla',joints:'Cadera, rodilla y tobillo',bones:'Pelvis, fémur, tibia y pie',muscles:'Glúteo mayor, cuádriceps y plantarflexores',phases:['Elevar la pierna adelantada','Transferir el peso','Extender y elevar el cuerpo'],mechanics:'La pierna adelantada recibe la carga al transferir el peso; aquí no se simula el contacto con el escalón.',question:'¿Qué músculos contribuyen a extender cadera y rodilla?',answer:'Glúteo mayor y cuádriceps, respectivamente.'},
{id:'footballkick',name:'Golpeo de fútbol',goal:'deporte',region:'inferior',level:'intermedio',movement:'footballkick',case:'sentadilla',joints:'Cadera y rodilla de golpeo; apoyo contralateral',bones:'Pelvis, fémur, tibia y pie',muscles:'Flexores de cadera, cuádriceps e isquiotibiales',phases:['Armado de la pierna','Aceleración de cadera y rodilla','Contacto y seguimiento'],mechanics:'La secuencia depende de pelvis y pie de apoyo. El balón y sus fuerzas de impacto no están modelados.',question:'¿Qué segmento acelera al extender la rodilla?',answer:'La pierna, especialmente el segmento tibia y pie.'},
{id:'curl',name:'Curl de bíceps',goal:'fuerza',region:'superior',level:'inicial',movement:'curl',case:'curl',joints:'Codo y radiocubital',bones:'Húmero, radio y cúbito',muscles:'Braquial, bíceps y braquiorradial',phases:['Codo cerca de la extensión','Flexión contra la resistencia','Retorno controlado'],mechanics:'El brazo de momento externo cambia con la orientación del antebrazo y la línea de fuerza.',question:'¿Qué músculo flexiona el codo con independencia de la posición del antebrazo?',answer:'El braquial es un flexor importante del codo.'}
];
const $=id=>document.getElementById(id);const grid=$('exercise-grid'),detail=$('exercise-detail');
let selected=null;const key='atlas-exercises-studied-v1';let studied=new Set;try{studied=new Set(JSON.parse(localStorage.getItem(key)||'[]'))}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filtered(){const q=$('exercise-search').value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');return exercises.filter(e=>['goal','region','level'].every(field=>$(field==='goal'?'exercise-goal':field==='region'?'exercise-region':'exercise-level').value==='all'||$(field==='goal'?'exercise-goal':field==='region'?'exercise-region':'exercise-level').value===e[field])&&`${e.name} ${e.muscles} ${e.joints}`.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q))}
function render(){const list=filtered();grid.innerHTML=list.map((e,i)=>`<button class="exercise-card ${selected===e.id?'active':''}" data-id="${e.id}" aria-pressed="${selected===e.id}"><span>${String(i+1).padStart(2,'0')} / ${e.goal==='fuerza'?'ENTRENAMIENTO':e.goal==='vida'?'VIDA DIARIA':'DEPORTE'}</span><strong>${esc(e.name)}</strong><small>${esc(e.joints)}</small><em>${studied.has(e.id)?'✓ Estudiado':'Explorar gesto →'}</em></button>`).join('');$('result-count').textContent=`${list.length} ejercicios`;$('empty').hidden=list.length>0;$('exercise-progress').textContent=`${studied.size} de ${exercises.length} gestos estudiados`;grid.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.id)))}
function select(id){const e=exercises.find(x=>x.id===id);if(!e)return;selected=id;render();detail.hidden=false;detail.innerHTML=`<div class="detail-head"><div><span class="eyebrow">FICHA DE ESTUDIO · ${e.level.toUpperCase()}</span><h2>${esc(e.name)}</h2><p>${esc(e.joints)}</p></div><button id="close-detail" aria-label="Cerrar ficha">×</button></div><div class="detail-grid"><section><h3>01 · Sigue las fases</h3><ol>${e.phases.map(p=>`<li>${esc(p)}</li>`).join('')}</ol><a class="primary" href="./vistas/explorar.html?movimiento=${encodeURIComponent(e.movement)}">Ver movimiento en el atlas 3D ↗</a></section><section><h3>02 · Construye el contexto</h3><dl><dt>Huesos</dt><dd>${esc(e.bones)}</dd><dt>Músculos relacionados</dt><dd>${esc(e.muscles)}</dd><dt>Biomecánica</dt><dd>${esc(e.mechanics)}</dd></dl><a href="./biomecanica/${encodeURIComponent(e.case)}.html">Estudiar el caso biomecánico ↗</a></section><section class="question"><h3>03 · Comprueba sin mirar</h3><p>${esc(e.question)}</p><button id="reveal">Mostrar respuesta</button><p id="answer" hidden>${esc(e.answer)}</p><button id="mark" class="mark">${studied.has(id)?'✓ Ya estudiado':'Marcar como estudiado'}</button></section></div>`;detail.querySelector('#close-detail').onclick=()=>{detail.hidden=true;selected=null;render()};detail.querySelector('#reveal').onclick=()=>{detail.querySelector('#answer').hidden=false};detail.querySelector('#mark').onclick=()=>{studied.add(id);localStorage.setItem(key,JSON.stringify([...studied]));select(id)};detail.scrollIntoView({behavior:'smooth',block:'start'})}
['exercise-search','exercise-goal','exercise-region','exercise-level'].forEach(id=>$(id).addEventListener(id==='exercise-search'?'input':'change',()=>{selected=null;detail.hidden=true;render()}));$('surprise').onclick=()=>{const options=filtered().filter(e=>e.id!==selected);if(options.length)select(options[Math.floor(Math.random()*options.length)].id)};try{document.documentElement.dataset.theme=localStorage.getItem('atlas-theme')||'light'}catch{}render();
